package org.mcrf.client

/** Labels accompany the actual canonical fields; runtime validators remain the authority. */
object CompatibilityImportFields {
    fun describe(key: String): Pair<String, String> = when (key) {
        "server", "domain" -> "Адрес сервера" to "Домен или IP сервера без схемы и пути. Для DNSTT — делегированный домен туннеля."
        "server_port", "wg_port", "raw_port", "local_port" -> "Порт · $key" to "Порт 1–65535 из конфигурации. RAW и WireGuard могут использовать разные порты."
        "password", "secret" -> "Пароль / секрет" to "Секрет доступа из конфигурации провайдера; сохраняется в зашифрованном каталоге."
        "key" -> "Ключ сервера" to "Публичный ключ DNSTT или ключ комнаты OLC: 64 шестнадцатеричных символа."
        "doh", "dot", "udp" -> "Резолвер · $key" to "Ровно один транспорт DNS: DoH — HTTPS URL; DoT — домен:порт; UDP — IP:порт."
        "username" -> "Логин" to "Необязательная авторизация прокси DNSTT. Логин и пароль задаются вместе."
        "workers" -> "Параллельные потоки" to "Число кратно 9 и зависит от числа звонков; превышение лимита не сохраняется."
        "vk_call_count" -> "Автоматических VK-звонков" to "Для QWDTT: 1–32. Звонки создаются только при подключении, не при проверке задержки. Ручные ссылки имеют приоритет; без этого поля старые профили используют 6."
        "mode" -> "Режим QWDTT" to "wg — через WireGuard; raw — прямой IP-туннель с отдельным RAW-портом. Сервер должен поддерживать выбранный режим."
        "turn_tcp" -> "TURN через TCP" to "Выключено — UDP. TCP иногда помогает в ограниченных сетях, но повышает задержку."
        "captcha_mode" -> "Капча" to "Авто — автоматические способы с ручной проверкой при необходимости; Вручную — окно VK по уведомлению."
        "obfs" -> "Маскировка звонка" to "audio или video; значение должно совпадать с поддерживаемым режимом сервера."
        "vk_anon_path" -> "Доступ к звонкам VK" to "vkcalls — обычный путь звонка; legacy — прежний путь с капчей."
        "go_dns", "dns" -> "DNS движка" to "Резолвер служебных запросов движка, отдельно от DNS трафика VPN."
        "provider" -> "Провайдер OLC" to "jitsi, telemost или wbstream. Не все транспорты доступны у каждого сервиса."
        "transport" -> "Транспорт OLC" to "datachannel, vp8channel, seichannel или videochannel; поддержка зависит от провайдера."
        "room", "url" -> "Комната / ссылка" to "Полная ссылка комнаты выбранного сервиса. Для Jitsi требуется домен и путь комнаты."
        "token" -> "Токен сервиса" to "Токен доступа WBStream. Не публикуй его; для datachannel обязателен."
        "channel" -> "Канал комнаты" to "Идентификатор канала, предоставленный сервисом."
        "dial" -> "Прямой адрес" to "Адрес:порт транспорта direct. Разрешён только с согласованием OpenFlux."
        "codec" -> "Кодек OpenFlux" to "batched — группировать данные; legacy — прежний формат. Нужна совместимость сервера."
        "negotiate" -> "Согласование OpenFlux" to "Включает защищённое согласование транспорта. Нужен секрет длиной от 16 символов."
        "context" -> "Контекст OpenFlux" to "Контекст из профиля сервера; значение участвует в согласовании."
        "fingerprint" -> "Отпечаток TLS" to "android, chrome, firefox, safari или ios. Выбери поддерживаемый движком вариант."
        "device_id" -> "ID устройства" to "Необязательный ID SWG из своего профиля. MCRF не копирует идентификаторы из примеров."
        "vp8-fps", "fps", "video-fps" -> "Кадров в секунду · $key" to "Частота кадров транспорта OLC: 1–120. Больше кадров — больше нагрузки и служебного трафика."
        "vp8-batch", "batch" -> "Кадров в пакете · $key" to "Объединение кадров OLC: 1–64. Большой пакет увеличивает задержку, но сокращает служебные расходы."
        "frag" -> "Размер фрагмента SEI" to "Фрагмент OLC: 1–65535 байт. Должен соответствовать ограничению транспорта сервера."
        "ack-ms" -> "Ожидание ACK, мс" to "Пауза подтверждения OLC: 1–60000 мс. Малое значение повышает частоту подтверждений."
        "video-w", "video-h" -> "Размер видео · $key" to "Размер кадра OLC: 1–4096 пикселей. Для Tile нужны ширина и высота 1080."
        "video-qr-size" -> "QR-фрагмент видео" to "Размер QR-фрагмента OLC: 0–65535. Ноль позволяет движку выбрать размер автоматически."
        "video-tile-module" -> "Размер модуля Tile" to "Размер модуля OLC: 1–270. Влияет на плотность данных и устойчивость видеоканала."
        "video-tile-rs" -> "Восстановление Tile" to "Избыточность восстановления OLC: 0–200. Большее значение повышает устойчивость и расход трафика."
        "video-codec" -> "Кодек видео OLC" to "qrcode или tile. Для tile нужны кадры 1080×1080 и совместимый сервер."
        "video-qr-recovery" -> "Восстановление QR" to "low, medium, high или highest. Более сильное восстановление уменьшает полезную ёмкость кадра."
        else -> key to "Параметр выбранного движка из исходного профиля. Значение проверяется его валидатором; остальные поля сохраняются."
    }
}
